fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    for i in 0..n / 2 {
        let left = text[i];
        let right = text[n - 1 - i];
        
        // Convert to lowercase for ASCII uppercase letters only
        let left_lower = if left.is_ascii_uppercase() {
            left.to_ascii_lowercase()
        } else {
            left
        };
        
        let right_lower = if right.is_ascii_uppercase() {
            right.to_ascii_lowercase()
        } else {
            right
        };
        
        if left_lower != right_lower {
            return false;
        }
    }
    true
}